def transform(grid):
    h, w = len(grid), len(grid[0])
    separators = set()
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and (r == 0 or row[0] == grid[r-1][0] or True):
            # Full-width uniform lines separate the panels.
            if all(v == row[0] for v in row):
                separators.add(("r", r, row[0]))
    row_seps = {r for axis, r, _ in separators}
    col_seps = set()
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            col_seps.add(c)
    # Keep only full-length lines; rows/columns are detected from uniformity.
    row_ranges = []
    start = 0
    for r in range(h):
        if r in row_seps:
            if start < r:
                row_ranges.append((start, r))
            start = r + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for c in range(w):
        if c in col_seps:
            if start < c:
                col_ranges.append((start, c))
            start = c + 1
    if start < w:
        col_ranges.append((start, w))
    # The common panel fill is the most frequent color outside separators.
    sep_colors = {color for _, _, color in separators}
    for c in col_seps:
        sep_colors.add(grid[0][c])
    from collections import Counter
    counts = Counter(grid[r][c] for a,b in row_ranges for r in range(a,b)
                     for x,y in col_ranges for c in range(x,y))
    background = counts.most_common(1)[0][0]
    out = [[background for _ in col_ranges] for _ in row_ranges]
    for i, (ra, rb) in enumerate(row_ranges):
        for j, (ca, cb) in enumerate(col_ranges):
            object_count = sum(grid[r][c] != background for r in range(ra, rb) for c in range(ca, cb))
            if object_count >= 2:
                out[i][j] = 1
    return out

